public class CirculationReport {static String batchPrint(LibraryMember[]m){StringBuilder b=new StringBuilder();for(LibraryMember x:m){b.append(x instanceof StudentMember?"Student":"General").append(" | Books: ").append(x.getBooksBorrowed()).append(" | ");}return b.toString();}public static void main(String[]a){System.out.println(batchPrint(new LibraryMember[]{new LibraryMember("LIB1",3)}));}}
